// 原完整EncounterLeave两端复行后读源；测试调用真实Interaction writer，未借模拟结清。
#define main private_shop_original_travel_expense_main
#include "private_shop_travel_expense_source_test.cpp"
#undef main
#include "resident/domains/commerce/freight/private_shop_travel_encounter_leave_source.hpp"
#include "resident/storage/common_codec.hpp"
#include <limits>
namespace {
// 复用原真实路线，先取几何命中，再原step真正付费落点。
ContactHit paid_contact(Fixture& f,bool terrain_mode){f.catalog.road_encounters=true;
 if(terrain_mode){terrain::TerrainMap map;map.id="map";map.width=40;map.height=20;map.cell_size=20;map.cells.resize(2);map.budgets={{terrain::Mode::foot,100},{terrain::Mode::army,100},{terrain::Mode::boat,100}};map.money_per_tick=7;map.fatigue_per_tick=2;require(terrain::validate_map(map).ok,"actual contact map");f.catalog.world_map_id=map.id;f.catalog.maps.insert(map.id,map);f.catalog.settlements.find("A")->map_xy={10,10};f.catalog.settlements.find("B")->map_xy={30,10};}
 auto other=f.begin("other","A");if(!terrain_mode){require(step_travel(f.common,f.travel,f.catalog,f.services,other).ok,"actual other first road step");++f.common.state().identity.tick;}
 auto carrier=f.begin("carrier","B");auto batch=detect_travel_contacts(f.common,f.travel,f.catalog,f.services,19);require(batch.ok&&batch.value.ordered_hits.size()==1,"actual selected contact hit");
 require(step_travel(f.common,f.travel,f.catalog,f.services,carrier).ok,"carrier actual paid contact step");require(step_travel(f.common,f.travel,f.catalog,f.services,other).ok,"other actual paid contact step");return batch.value.ordered_hits.front();
}
// 沿原phase构造字段，callback随后单独绑定；不把任意字符串当原命中授权。
EncounterInstall installation(const ContactHit& h){EncounterInstall out;out.leaders={h.a,h.b};if(h.road){out.action_ids={h.road->first.trace.action_id,h.road->second.trace.action_id};out.anchors={h.road->first.anchor,h.road->second.anchor};out.resume_paused={h.road->first.trace.params.paused,h.road->second.trace.params.paused};for(auto& order:out.anchor_field_orders)order={"kind","edge_id","origin","progress"};out.anchors_order={h.a,h.b};if(out.action_ids[0]>out.action_ids[1])std::swap(out.anchors_order[0],out.anchors_order[1]);}else{out.action_ids={h.first.trace.action_id,h.second.trace.action_id};out.anchors={h.first.anchor,h.second.anchor};out.resume_paused={h.first.trace.params.paused,h.second.trace.params.paused};}return out;}

// 原安装后推进到该Encounter真实created_tick，作为稳定道别前界；不是World阶段测试。
StableId pending_contact(Fixture& f,InteractionState& state,bool terrain_mode){auto hit=paid_contact(f,terrain_mode);auto op=installation(hit);op.apply_motion=[&](const StableId& id,bool active){return apply_contact_truncation(f.common,f.travel,hit,id,active);};auto installed=install_encounter(f.common,state,"carrier",op);require(installed.ok,"actual pending Encounter installation");++f.common.state().identity.tick;return installed.value;}
void actual_leave(bool terrain_mode){Fixture f;InteractionState state;const auto id=pending_contact(f,state,terrain_mode);InteractionCatalog catalog;InteractionAccess access;EncounterLeave command{id};std::array<TravelEncounterResumeDraft,2> resumes;std::size_t count=0;PrivateShopTravelEncounterLeaveBoundary boundary;bool premature=false;
 access.set_journey_encounter=[&](const StableId& action,const StableId& encounter,bool paused){if(!encounter.empty()||count>=2)return common_failure("WrongOriginalResume");std::optional<TravelEncounterResumeDraft> d;auto status=resume_after_encounter(f.common,f.travel,action,paused,&d);if(!status.ok)return status;if(!d)return common_failure("MissingOriginalResume");resumes[count++]=*d;premature=!read_private_shop_travel_encounter_leave(f.common,f.travel,state,boundary,resumes,InteractionEffect{}).ok;return common_success();};
 auto quote=preview_interaction(f.common,state,catalog,access,"carrier",command);require(quote.ok,"actual original leave quote");require(f.common.begin_resource_execution_capture().ok,"original leave capture");auto b=capture_private_shop_travel_encounter_leave_boundary(f.common,f.travel,state,"carrier",command,quote.value);require(b.ok,"original leave boundary");boundary=b.value;const auto next=f.common.state().next_instance_id;const auto funds=f.funds("carrier");auto result=apply_interaction(f.common,state,catalog,access,"carrier",command,quote.value);require(result.ok&&count==2,"actual two-sided leave writer");require(read_private_shop_travel_encounter_leave(f.common,f.travel,state,b.value,resumes,result.value).ok,"actual whole leave source");check(premature&&state.encounters.front().resolved_tick==f.common.tick()&&f.common.state().next_instance_id==next+1,"resume callbacks are not resolution; only one real internal result");check(f.common.resource_execution_drafts().empty()&&f.funds("carrier")==funds&&f.common.action(resumes[0].before.action.id)&&f.common.action(resumes[1].before.action.id),"leave no refund charge action release or arrival");
 auto bad=resumes;std::swap(bad[0],bad[1]);check(!read_private_shop_travel_encounter_leave(f.common,f.travel,state,b.value,bad,result.value).ok,"two original action slots cannot swap");bad=resumes;bad[0].original_resume_paused=!bad[0].original_resume_paused;check(!read_private_shop_travel_encounter_leave(f.common,f.travel,state,b.value,bad,result.value).ok,"old pause cannot be chosen anew");auto wrong=result.value;wrong.settlement_result="result.other";check(!read_private_shop_travel_encounter_leave(f.common,f.travel,state,b.value,resumes,wrong).ok,"actual internal result must match");auto record=state.encounters.front();state.encounters.front().resolved_tick++;check(!read_private_shop_travel_encounter_leave(f.common,f.travel,state,b.value,resumes,result.value).ok,"leave is actual zero-time boundary");state.encounters.front()=record;
 require(f.common.finish_resource_execution_capture().ok,"finish leave capture");require(f.common.begin_resource_execution_capture().ok,"restart leave capture");check(!read_private_shop_travel_encounter_leave(f.common,f.travel,state,b.value,resumes,result.value).ok,"leave old boundary cannot consume restarted capture");}
// 原第二callback拒绝时第一边确已恢复，整笔仍须原Common/Travel/Interaction保存集撤回。
void failed_second_resume(){Fixture f;InteractionState state;const auto id=pending_contact(f,state,false);InteractionCatalog catalog;InteractionAccess access;EncounterLeave cmd{id};std::array<TravelEncounterResumeDraft,2> drafts;int calls=0;access.set_journey_encounter=[&](const StableId& action,const StableId&,bool paused){if(calls++)return common_failure("SecondResumeRefused");std::optional<TravelEncounterResumeDraft> d;auto st=resume_after_encounter(f.common,f.travel,action,paused,&d);if(st.ok&&d)drafts[0]=*d;return st;};auto q=preview_interaction(f.common,state,catalog,access,"carrier",cmd);require(q.ok,"failed callback actual quote");require(f.common.begin_resource_execution_capture().ok,"failed leave capture");auto b=capture_private_shop_travel_encounter_leave_boundary(f.common,f.travel,state,"carrier",cmd,q.value);require(b.ok,"failed leave original boundary");const auto travel=f.travel;const auto interactions=state;const auto common=encode_common_state(f.common.state());auto save=f.common.begin_savepoint();require(save.ok,"original leave savepoint");auto result=apply_interaction(f.common,state,catalog,access,"carrier",cmd,q.value);check(!result.ok&&calls==2&&!drafts[0].original_encounter_id.empty(),"first resume happened before second callback failed");check(!read_private_shop_travel_encounter_leave(f.common,f.travel,state,b.value,drafts,{}).ok,"partial leave has no source");require(f.common.rollback_savepoint(save.value).ok,"original leave rollback");f.travel=travel;state=interactions;check(compare_boundary(common,encode_common_state(f.common.state())).exact(),"leave original Common unchanged after rollback");}
}
int main(){try{actual_leave(false);actual_leave(true);failed_second_resume();}catch(const std::exception& e){check(false,e.what());}std::cout<<"PRIVATE_SHOP_ENCOUNTER_LEAVE_CHECKS="<<checks<<" FAILURES="<<failures<<'\n';return failures?1:0;}
